public class WordFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.Optional<String> found = WordFinder.firstLongerThan(new String[] {"a", "bbbb", "ccccc"}, 3);
        check("finds a match", true, found.isPresent());
        check("match value", "bbbb", found.orElse("none"));
        check("first match wins", "aaaa", WordFinder.firstLongerThan(new String[] {"aaaa", "bbbbb"}, 2).orElse("none"));
        java.util.Optional<String> missing = WordFinder.firstLongerThan(new String[] {"cat", "dog"}, 5);
        check("no match is empty", true, missing.isEmpty());
        check("no match orElse", "none", missing.orElse("none"));
        check("exact length does not count", "none", WordFinder.firstLongerThan(new String[] {"abc"}, 3).orElse("none"));
        check("empty array", "none", WordFinder.firstLongerThan(new String[] {}, 0).orElse("none"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

