public class WordFinder {

    public static java.util.Optional<String> firstLongerThan(String[] words, int len) {
        for (String word : words) {
            if (word.length() > len) {
                return java.util.Optional.of(word);
            }
        }
        return java.util.Optional.empty();
    }
}
